// @ts-nocheck — this is the wrangler entry, not part of the Next app. It
// statically imports `../.open-next/worker.js`, which OpenNext only emits
// during `opennextjs-cloudflare build` (after `next build`). That module
// therefore can't exist at type-check time, so type-checking this glue
// file is impossible by construction; wrangler resolves the import at
// bundle time, once the file has been generated.
/**
 * @packageDocumentation
 *
 * Production Worker entry point.
 *
 * The Next.js handler is generated by OpenNext into `.open-next/worker.js`.
 * This file forwards `fetch` to it and adds the site's response headers
 * (see `lib/http/headers.ts`). It is a thin wrapper (rather than pointing
 * `wrangler.jsonc` straight at the generated file) so Worker-level additions —
 * cron handlers, Workflow exports, Durable Objects — have an obvious home.
 *
 * Deployment glue:
 *
 *   1. `wrangler.jsonc` -> `main` set to this file (`src/worker.ts`).
 *   2. `next build && opennextjs-cloudflare build` produces
 *      `.open-next/worker.js`.
 *   3. `wrangler deploy` bundles this file.
 */

import openNextHandler from '../.open-next/worker.js';
import {
  edgeCache,
  edgeCacheKey,
  isEdgeCacheable,
  storableCopy,
} from './lib/http/edge-cache';
import { buildCsp, forwardedHeaders, newNonce } from './lib/http/csp';
import { applyResponseHeaders, replacingHeaders } from './lib/http/headers';

/** The response with one more header (responses from the app are read-only). */
function withHeader(response: Response, name: string, value: string): Response {
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers: replacingHeaders(response.headers, { [name]: value }),
  });
}

/** The Worker itself: forwards each request to the app and adds the site's headers. */
const handler: ExportedHandler<CloudflareEnv> = {
  /**
   * Public pages come from the edge copy when there is one; everything else is
   * forwarded to OpenNext's Next.js handler. Either way the site's security and
   * cache headers are added to whatever goes back.
   */
  async fetch(request, env, ctx) {
    const cache = edgeCache();
    const cacheable = cache !== undefined && isEdgeCacheable(request);
    const key = cacheable
      ? edgeCacheKey(request, env.CF_VERSION_METADATA?.id ?? 'dev')
      : undefined;
    if (cache && key) {
      const hit = await cache.match(key);
      if (hit) {
        return applyResponseHeaders(request, hit);
      }
    }
    // Each page gets its own Content Security Policy, with a one-time number the
    // app puts on its scripts. The policy goes to the app on the request (that
    // is where Next.js looks for the number) and back to the browser on the
    // response, whether the page is rendered now or comes from the edge copy.
    const nonce = newNonce();
    // The approval screen may not be framed by anyone, not even this site.
    const csp = buildCsp(
      nonce,
      new URL(request.url).pathname === '/oauth/authorize' ? 'none' : 'self',
    );
    const forwarded = new Request(request, {
      headers: forwardedHeaders(request.headers, csp, nonce),
    });
    const app = openNextHandler as ExportedHandler<CloudflareEnv>;
    if (!app.fetch) {
      throw new Error('The OpenNext worker has no fetch handler.');
    }
    const fetched = await app.fetch(forwarded, env, ctx);
    const isHtml = (fetched.headers.get('content-type') ?? '').startsWith(
      'text/html',
    );
    const response =
      isHtml && !fetched.headers.has('content-security-policy')
        ? withHeader(fetched, 'Content-Security-Policy', csp)
        : fetched;
    if (cache && key) {
      const copy = storableCopy(response);
      if (copy) {
        ctx.waitUntil(cache.put(key, copy));
      }
    }
    return applyResponseHeaders(request, response);
  },
};

export default handler;
